import json
from collections import OrderedDict
from pathlib import Path

cfg = json.loads(Path('/root/config.json').read_text())
block_size = cfg['block_size']
capacity = cfg['cache_capacity_blocks']
assert cfg['policy'] == 'S3FIFO'
small_cap = round(capacity * cfg['s3fifo']['small_ratio'])
max_freq = cfg['s3fifo']['max_freq']
main_cap = capacity - small_cap

def admit_to_G(h, G):
    if h in G:
        del G[h]
    elif len(G) >= main_cap:
        G.popitem(last=False)
    G[h] = None


def admit_to_M(h, freq, M, G):
    while len(M) >= main_cap:
        victim, vf = next(iter(M.items()))
        if vf >= 1:
            M.popitem(last=False)
            M[victim] = vf - 1
        else:
            M.popitem(last=False)
            admit_to_G(victim, G)
            break
    M[h] = freq


def admit_to_S(h, S, M, G):
    while len(S) >= small_cap:
        victim, vf = S.popitem(last=False)
        if vf >= 1:
            admit_to_M(victim, vf, M, G)
        else:
            admit_to_G(victim, G)
    S[h] = 0

S = OrderedDict()
M = OrderedDict()
G = OrderedDict()

report = {
    'total_requests': 0,
    'total_prompt_tokens': 0,
    'total_hit_tokens': 0,
    'overall_hit_rate': 0.0,
    'final_cache_blocks': 0,
    'per_request': [],
}

for idx, line in enumerate(Path('/root/trace.jsonl').open()):
    if not line.strip():
        continue
    req = json.loads(line)
    L = req['input_length']
    hash_ids = req['hash_ids']
    k = 0
    for h in hash_ids:
        if h in S or h in M:
            k += 1
        else:
            break
    hit_tokens = min(k * block_size, L)

    report['per_request'].append({'idx': idx, 'prompt_tokens': L, 'hit_tokens': hit_tokens})
    report['total_requests'] += 1
    report['total_prompt_tokens'] += L
    report['total_hit_tokens'] += hit_tokens

    # access every block in order
    for h in hash_ids:
        if h in S or h in M:
            if h in S:
                S[h] = min(S[h] + 1, max_freq)
            else:
                M[h] = min(M[h] + 1, max_freq)
        elif h in G:
            del G[h]
            admit_to_M(h, 0, M, G)
        else:
            admit_to_S(h, S, M, G)

report['overall_hit_rate'] = report['total_hit_tokens'] / report['total_prompt_tokens'] if report['total_prompt_tokens'] else 0.0
report['final_cache_blocks'] = len(S) + len(M)

Path('/root/report.json').write_text(json.dumps(report, separators=(',', ':')))
print(report['total_requests'], report['total_prompt_tokens'], report['total_hit_tokens'], report['overall_hit_rate'], report['final_cache_blocks'])
